using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using NonBaoHiemVietTin.Data; using NonBaoHiemVietTin.Infrastructure; using NonBaoHiemVietTin.Models;
namespace NonBaoHiemVietTin.Controllers;
public sealed class CartController(AppDbContext db):Controller { const string Key="cartSession"; [HttpGet] public IActionResult Index()=>View(HttpContext.Session.GetJson<List<CartItem>>(Key)??[]);
[HttpPost] public async Task<IActionResult> AddItem(int ProductId,int Quantity){var p=await db.Products.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==ProductId&&x.IsDelete!=true&&x.Status==true);if(p==null)return Json(new{status=-2});if(Quantity<1||Quantity>(p.Quantity??0))return Json(new{status=-3,message="Không đủ hàng"});var list=HttpContext.Session.GetJson<List<CartItem>>(Key)??[];var item=list.FirstOrDefault(x=>x.Product.Id==ProductId);if(item==null)list.Add(new CartItem{Product=p,Quantity=Quantity});else if(item.Quantity+Quantity<=(p.Quantity??0))item.Quantity+=Quantity;else return Json(new{status=-3,message="Không đủ hàng"});HttpContext.Session.SetJson(Key,list);return Json(new{status=1,sumQuantity=list.Sum(x=>x.Quantity)});}
[HttpPost] public IActionResult DeleteItem(int ProductId){var list=HttpContext.Session.GetJson<List<CartItem>>(Key)??[];list.RemoveAll(x=>x.Product.Id==ProductId);HttpContext.Session.SetJson(Key,list);return Json(new{status=1,sumQuantity=list.Sum(x=>x.Quantity)});}
}
